import { gql } from '@apollo/client/core';

export const fetchAllContactsByUrl = gql`
query {
  leads(
    filters: { 

      advUrl: { notNull: true, ne: "" }
    },
    pagination: { limit: 1000 }
  ) {
    data {
      id
      attributes {
        no
        project
        user
        name
        language
        phoneNumber
        status
        phoneId
        interaction
        lastCall
        nextCall
        called
        rating
        dialedDate
        sourceDate
        contacted
        message
        doc
        stage
        source
        occupation
        requestType
        process
        task
        delegate
        address
        advUrl
        advUrlDate
        facebookUrl
        notionUrl
        updatedAt
      }
    }
  }
}
`;

