<template>
  <v-dialog v-model="internalDialogVisible" persistent max-width="390" class="top-dialog">
    <v-card>
      <v-card-title>Enter Call Status</v-card-title>
      <v-card-text>
        <textarea v-model="internalInteraction_" placeholder="Interaction" class="e-input bordered-input" rows="3">
      </textarea>
      </v-card-text>
      <v-card-actions class="d-flex justify-space-between">
        <v-container class="pa-0">
          <v-row>
            <!-- First Row -->
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('eg')">EG</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('nr')">NR</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('ni')">NI</v-btn>
            </v-col>
            
          </v-row>
          <v-row>
            <!-- Second Row -->
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('cbr')">CBR</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('nis')">NIS</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('mbx')">MBX</v-btn>
            </v-col>
           
          </v-row>

          <v-row>
           <!-- Second Row -->
          <v-col cols="4">
            <v-btn text class="bordered-btn" @click="confirmStatus2('fp')">FP</v-btn>
          </v-col>

          <v-col cols="4">
            <v-btn text class="bordered-btn" @click="confirmStatus2('fpi')">FP I</v-btn>
          </v-col>
   
          <v-col cols="4">
            <v-btn text class="bordered-btn" @click="confirmStatus2('niw')">Wrong #</v-btn>
          </v-col>
        </v-row>
          <v-row>
            <!-- Cancel and OK Buttons -->
            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('ok')">OK I</v-btn>
            </v-col>

            <v-col cols="4">
              <v-btn text class="bordered-btn" @click="confirmStatus2('qualify')">Qualify</v-btn>
            </v-col>
            <v-col cols="4">
              <v-btn text color="red" class="bordered-btn" @click="closeDialog">Cancel</v-btn>
            </v-col>
          </v-row>
        </v-container>
      </v-card-actions>
    </v-card>
  </v-dialog>

</template>

<script>
import { ref, watch, defineComponent } from 'vue';

export default defineComponent({
  name: 'statusDialog',
  props: {
    showDialog: {
      type: Boolean,
      required: true
    },
    selectedStatus: {
      type: String,
      default: ''
    },
    interaction: {
      type: String,
      default: ''
    },
    rating: {
      type: Number,
      default: 0
    }
  },
  emits: ['update:showDialog', 'updateStatus'],
  setup(props, { emit }) {
    // Reactive properties
    const internalDialogVisible = ref(props.showDialog);
    const internalSelectedStatus = ref(props.selectedStatus);
    const internalSelectedStatus_ = ref("");
    const internalInteraction = ref(props.interaction);
    const internalInteraction_ = ref("");
    const internalRating = ref(props.rating);
    //nis : not in service, cbr:can not be reach, eg:engage,nr:no respond,ua: unavailable,crl:call reject
    const statusOptions = ['✓', 'ni', 'nis', 'cbr', 'eg', 'XXX', 'nr', 'ua', 'crj', 'mbx','fp'];

    // Watch for prop changes and sync with internal state
    watch(() => props.showDialog, (newVal) => {
      internalDialogVisible.value = newVal;
    });

    watch(() => props.interaction, (newVal) => {
      internalInteraction.value = newVal;
    });

    watch(() => props.rating, (newVal) => {
      internalRating.value = newVal;
    });

    watch(() => props.selectedStatus, (newVal) => {
      internalSelectedStatus.value = newVal;
    });


    // Watch internal dialog visibility and emit back to parent
    watch(internalDialogVisible, (newVal) => {
      emit('update:showDialog', newVal);
    });

    // const confirmStatus2 = () => {
    //   emit('updateStatus', internalSelectedStatus.value, dd: mm: hr + internalInteraction.value + internalInteraction.value);
    //   closeDialog();
    // };

    const confirmStatus2 = (cm) => {
      const now = new Date();
      const month = now.getMonth() + 1; // Get the month in numeric format (1 to 12)
      const day = now.getDate(); // Get the day of the month
      let hour = now.getHours(); // Get the hour (24-hour format)
      const period = hour >= 12 ? 'P' : 'A'; // Determine AM or PM

      hour = hour % 12 || 12; // Convert hour to 12-hour format

      const formattedDateTime = `(${day}/${month} ${hour}${period}) `;



      switch (cm) {
        case "nr":
        case "ni":
        case "nis":
        case "cbr":
        case "mbx":
        case "eg":
        case "fp":
          internalInteraction_.value = "";
          internalSelectedStatus.value = cm;
          break;
        case "ok":
          internalSelectedStatus.value = cm;
          if (!internalInteraction_.value.includes(".") && internalInteraction_.value.length > 0) {
            internalInteraction_.value += ".";
          }
          break;
          case "fpi":
          internalSelectedStatus.value = "fp";
          if (!internalInteraction_.value.includes(".") && internalInteraction_.value.length > 0) {
            internalInteraction_.value += ".";
          }
          break;
          case "niw":
          internalSelectedStatus.value = "ni";
          internalInteraction_.value ="Wrong Number.";
          break;
          case "qualify":
          internalSelectedStatus.value = cm;
          if (!internalInteraction_.value.includes(".") && internalInteraction_.value.length > 0) {
            internalInteraction_.value += ".";
          }
          internalRating.value = 4;
          break;
        default:
          // Optional: Handle cases where `cm` doesn't match any case
          alert("Error# 156 unknow selection [" + cm);
          break;
      }

      emit(
        'updateStatus',
        `${internalSelectedStatus_.value} ${internalSelectedStatus.value}`,
        `${formattedDateTime}${internalInteraction_.value} \n${internalInteraction.value}`
      );
      closeDialog();
    };

    const closeDialog = () => {
      internalDialogVisible.value = false;
    };

    return {
      internalDialogVisible,
      internalSelectedStatus,
      internalSelectedStatus_,
      internalInteraction,
      internalInteraction_,
      internalRating,

      statusOptions,
      confirmStatus2,
      closeDialog
    };
  }
});
</script>

<style scoped>
/* Style for the bordered input */
.bordered-input {
  border: 1px solid #ccc;
  /* Light gray border */
  border-radius: 5px;
  /* Rounded corners */
  padding: 8px;
  /* Add padding inside the textarea */
  width: 100%;
  /* Make the textarea stretch to fit its container */
  box-sizing: border-box;
  /* Include padding and border in width calculation */
  resize: vertical;
  /* Allow resizing vertically only */
  font-family: inherit;
  /* Use the same font as the surrounding text */
  font-size: inherit;
  /* Match the surrounding font size */
}

/* Optional: Add hover effect */
.bordered-input:hover {
  border-color: #1976d2;
  /* Change border color on hover */
}

/* Optional: Add focus effect */
.bordered-input:focus {
  border-color: #1976d2;
  /* Change border color when focused */
  outline: none;
  /* Remove the default focus outline */
  box-shadow: 0 0 4px #1976d2;
  /* Add a subtle glow effect */
}

.bordered-btn {
  border: 1px solid #ccc !important;
  /* Add border explicitly */
  border-radius: 5px;
  /* Rounded corners */
  padding: 8px;
  /* Add spacing */
  background-color: transparent;
  /* Ensure transparency for text buttons */
}

.bordered-btn.with-border {
  border: 1px solid #ccc !important;
  /* Override Vuetify styles if `text` is used */
}

.bordered-btn:hover {
  border-color: #1976d2 !important;
  /* Change border color on hover */
}

.top-dialog {
  margin-top: 0 !important;
}

.top-dialog .v-dialog {
  margin-top: 0 !important;
  position: fixed !important;
  top: 160px !important;
}
</style>
