<template>
  <div>
    <h1>Import Contacts from CSV</h1>
    <input type="file" @change="handleFileUpload" accept=".csv" />
    <button @click="importContacts">Import</button>

    <div v-if="failedImports.length">
      <h2>Failed Imports</h2>
      <ul>
        <li v-for="(error, index) in failedImports" :key="index">
          Line {{ error.line }}: {{ error.message }}
        </li>
      </ul>
    </div>

    <div v-if="successfulImports > 0">
      <h2>Successfully Updated Records: {{ successfulImports }}</h2>
    </div>
  </div>
</template>

<script>
import { ref } from 'vue';
import { formatPhoneNumber2, createOrUpdateContactByKeys } from '../utils/contactUtils.js'; // Adjust the import to your actual function file
import Papa from 'papaparse'; // You'll need to install PapaParse for CSV parsing

export default {
  setup() {
    const failedImports = ref([]);
    const contactsData = ref([]);
    const successfulImports = ref(0); // New reactive variable to track successful imports

    const handleFileUpload = (event) => {
      const file = event.target.files[0];
      if (file) {
        Papa.parse(file, {
          header: true, // Set to true to use the first line as headers
          complete: (results) => {
            contactsData.value = results.data; // Store parsed data
          },
          error: (error) => {
            console.error('Error parsing CSV file:', error);
          },
        });
      }
    };

    const importContacts = async () => {
      console.log("#1");
      failedImports.value = []; // Clear previous errors
      successfulImports.value = 0; // Reset successful imports count

      for (let i = 0; i < contactsData.value.length; i++) {
        const contact = contactsData.value[i];
        const contactData = {
          no: i + 3, // Set sequential number for each record
          name: contact.name,
          phoneNumber: formatPhoneNumber2(contact.phoneNumber),
          project: contact.project,
          called: contact.called,
          contacted: contact.contacted,
          phoneId: contact.phoneId,
          requestType: contact.requestType,
          process: contact.process,
          stage: contact.stage,
          task: contact.task,
          delegate: contact.delegate,
          address: contact.address,
          advUrl: contact.advUrl,
          advUrlDate: contact.advUrlDate,
          facebookUrl: contact.facebookUrl,
          notionUrl: contact.notionUrl,
        };

        try {
          await createOrUpdateContactByKeys(contactData);
          successfulImports.value++; // Increment successful imports count
        } catch (error) {
          // Report the error with the line number
          failedImports.value.push({
            line: i + 1,
            message: error.message || 'Failed to update or create contact',
          });
        }
      }

      // Show a success message or reset the input after processing
      if (failedImports.value.length === 0) {
        alert('All contacts imported successfully!');
      } else {
        alert('#322 Got Error!');
      }
    };

    return {
      failedImports,
      successfulImports, // Return the successfulImports variable
      handleFileUpload,
      importContacts,
    };
  },
};
</script>

