<template>
    <v-container>
        <v-btn @click="importData">Import Data</v-btn>
        <!-- File input for uploading CSV or JSON -->
        <v-file-input v-model="file" label="Choose file" accept=".csv,.json"></v-file-input>

        <!-- Optional: Displaying import results -->
        <v-alert v-if="importStatus" :type="importStatus.type" dismissible>
            {{ importStatus.message }}
        </v-alert>
    </v-container>
</template>

<script>
import { gql } from '@apollo/client';
import client from '../apollo-client'; // Adjust the path to your Apollo client
import { convertDMY2YMD, convertDMY2YMDtime, formatPhoneNumber2 } from '../utils/contactUtils.js';

export default {

    data() {
        return {
            file: null, // To hold the selected file
            fileContent: null, // To store the content of the file after reading
            importStatus: null, // To display import result message
        };
    },
    watch: {
        // Watch for changes in the file
        file(newFile) {
            if (newFile) {
                this.readFile(newFile);
            }
        }
    },
    methods: {
        removeTypename(obj) {
  if (obj === null || typeof obj !== 'object') return obj;

  if (Array.isArray(obj)) {
    return obj.map(item => this.removeTypename(item));
  }

  const cleanedObj = {};
  for (const [key, value] of Object.entries(obj)) {
    if (key !== '__typename') {
      cleanedObj[key] = this.removeTypename(value);
    }
  }
  return cleanedObj;
},
        convertToISOString(dateString) {
      // Assuming dateString might be in 'D-M-YYYY' format
      const parts = dateString.split('-');
      if (parts.length === 3) {
        const [day, month, year] = parts;
        const date = new Date(year, month - 1, day); // JS months are 0-based
        return date.toISOString(); // This will give you something like '2023-01-01T00:00:00.000Z'
      }
      // Handle invalid date format
      console.warn('Invalid date format:', dateString);
      return null;
    },
    // ... other methods including createOrUpdateContactByKeys where convertToISOString is used

        // Read the file when it's selected or changed
        readFile(file) {
            const reader = new FileReader();

            reader.onerror = (error) => {
                console.error('Error reading file:', error);
                this.importStatus = { type: 'error', message: 'Failed to read file.' };
            };

            reader.onload = (event) => {
                this.fileContent = event.target.result;
            };

            reader.readAsText(file);
        },

        // Parse the file content based on file type (CSV/JSON)
        parseFile(fileContent, fileType) {
            if (fileType === 'application/json') {
                return JSON.parse(fileContent); // Expecting an array of records
            } else if (fileType === 'text/csv') {
                // Assuming the CSV is simple (you might need a library like Papaparse for complex CSVs)
                return this.parseCSV(fileContent);
            }
            return [];
        },

        // A simple CSV parser (for demonstration, adjust as needed)
        parseCSV(csvContent) {
            const rows = csvContent.trim().split('\n');
            const headers = rows[0].split(','); // Assuming the first row is headers
            return rows.slice(1).map((row) => {
                const values = row.split(',');
                return headers.reduce((acc, header, index) => {
                    acc[header.trim()] = values[index]?.trim();
                    return acc;
                }, {});
            });
        },

        // Import data when the user clicks the button
        async importData() {
            if (!this.file || !this.fileContent) {
                this.importStatus = { type: 'error', message: 'Please select a file first.' };
                return;
            }

            try {
                const records = this.parseFile(this.fileContent, this.file.type);
                await this.importRecords(records);
            } catch (error) {
                this.importStatus = { type: 'error', message: 'An error occurred during parsing.' };
                console.error('Error in parsing:', error);
            }
        },

        // Import records one by one
        async importRecords(records) {
            try {
                for (let i = 0; i < records.length; i++) {
                    const record = records[i];
                    await this.createOrUpdateContactByKeys(record);
                }
                this.importStatus = { type: 'success', message: `${records.length} records imported successfully!` };
            } catch (error) {
                this.importStatus = { type: 'error', message: 'An error occurred during import.' };
                console.error('Error importing records:', error);
            }
        },

        // Same logic as in your original code to create or update contact records
        async createOrUpdateContactByKeys(contactData0) {
            const contactData = this.removeTypename(contactData0);

  if (contactData.advUrlDate) {
    contactData.advUrlDate = convertDMY2YMD(contactData.advUrlDate);
  } else {
    delete contactData.advUrlDate;
  }

  if (contactData.dialedDate) {
    contactData.dialedDate = convertDMY2YMDtime(contactData.dialedDate);
  } else {
    delete contactData.dialedDate;
  }

  // Handle sourceDate
  if (contactData.sourceDate) {
    contactData.sourceDate = convertDMY2YMD(contactData.sourceDate);
  } else {
    delete contactData.sourceDate;
  }

  // Handle lastCall and nextCall if they exist (see previous response)
  if (contactData.lastCall) {
    contactData.lastCall = this.convertToISOString(contactData.lastCall);
  } else {
    delete contactData.lastCall;
  }

  if (contactData.nextCall) {
    contactData.nextCall = this.convertToISOString(contactData.nextCall);
  } else {
    delete contactData.nextCall;
  }

  // Handle action
  if (contactData.action) {
    contactData.action = contactData.action.map(action => {
      const { ...rest } = action;
      return rest;
    });
  } else {
    delete contactData.action;
  }

  delete contactData.requestColor;
  delete contactData.id;
  delete contactData.stageEmoji;
  delete contactData.edit;
  delete contactData.editField;
  delete contactData.updatedAt;
  delete contactData.id;
  // Other field handling...

  const findContactQuery = gql`
    query findContact($phoneNumber: String!, $project: String!) {
      leads(filters: { phoneNumber: { eq: $phoneNumber }, project: { eq: $project } }) {
        data {
          id
        }
      }
    }
  `;

  try {
    const { data } = await client.query({
      query: findContactQuery,
      variables: {
        phoneNumber: formatPhoneNumber2(contactData.phoneNumber),
        project: contactData.project,
      },
      fetchPolicy: 'no-cache',
    });

    const existingContactId = data.leads.data.length > 0 ? data.leads.data[0].id : null;

    const mutation = existingContactId
  ? gql`
      mutation updateLead($id: ID!, $data: LeadInput!) {
        updateLead(id: $id, data: $data) {
          data {
            id
            attributes {
              name
              email
              phoneNumber
              viewDoc
              source
              status
              rating
              AppointmentDate
              NextFollowUpDate
              occupation
              project
              calledId
              visitCount
              interaction
              lastCall
              nextCall
              no
              user
              language
              called
              contacted
              message
              doc
              dialedDate
              phoneId
              sourceDate
              address
              advUrl
              advUrlDate
              facebookUrl
              notionUrl
              process
              delegate
              task
              parentId
              coBroked
              requestType
              name2
              stage
              assignee
              remark
              action {
                date
                task
                status
              }
              info
              location
              district
              document {
                description
                url
              }
              advertisement {
                description
                url
              }
            }
          }
        }
      }
    `
  : gql`
      mutation createLead($data: LeadInput!) {
        createLead(data: $data) {
          data {
            id
            attributes {
              name
              email
              phoneNumber
              viewDoc
              source
              status
              rating
              AppointmentDate
              NextFollowUpDate
              occupation
              project
              calledId
              visitCount
              interaction
              lastCall
              nextCall
              no
              user
              language
              called
              contacted
              message
              doc
              dialedDate
              phoneId
              sourceDate
              address
              advUrl
              advUrlDate
              facebookUrl
              notionUrl
              process
              delegate
              task
              parentId
              coBroked
              requestType
              name2
              stage
              assignee
              remark
              action {
                date
                task
                status
              }
              info
              location
              district
              document {
                description
                url
              }
              advertisement {
                advertiser
                url
              }
            }
          }
        }
      }
    `;

    if (contactData.name == "alvin")
    alert("me");
    if (contactData.id == "1024")
    alert("ff");
    const result = await client.mutate({
      mutation,
      variables: existingContactId ? { id: existingContactId, data: contactData } : { data: contactData },
    });

    return existingContactId ? result.data.updateLead.data : result.data.createLead.data;
  } catch (error) {
    console.error('Error in createOrUpdateContactByKeys:', error);
    throw error;
  }
},
    },
}
</script>