export function formatPhoneNumber2(phone) {
  if (!phone) return '';

  // Remove spaces and dashes
  const sanitizedPhone = phone.replace(/[\s-]/g, '');

  // Check if the number is already in a valid international format
  if (sanitizedPhone.startsWith('+60')) {
    return sanitizedPhone; // If it already starts with +60, return as is
  }

  // Try parsing the phone number assuming a default region of 'MY' (Malaysia)
  const phoneData = parsePhoneNumberFromString(sanitizedPhone, 'MY');

  if (phoneData && phoneData.isValid()) {
    // Format the phone number in international format (it will include the correct country code)
    return phoneData.formatInternational();
  } else {
    // If parsing fails or if it's a local Malaysian number without +60
    if (!sanitizedPhone.startsWith('60')) {
      // Add +60 only if it’s not already prefixed with '60'
      return `+60${sanitizedPhone}`;
    } else {
      // If it already starts with '60' (without the '+'), just add the '+'
      return `+${sanitizedPhone}`;
    }
  }
}


