export async function createOrUpdateContactByKeys(contactData) {
  // Convert dates as necessary
  if (contactData.advUrlDate) {
    contactData.advUrlDate = convertDMY2YMD(contactData.advUrlDate);
  } else {
    delete contactData.advUrlDate;
  }

  if (contactData.dialedDate) {
    contactData.dialedDate = convertDMY2YMDtime(contactData.dialedDate);
  } else {
    delete contactData.dialedDate;
  }

  // Step 1: Check if a contact with the same phoneNumber and project already exists
  const findContactQuery = gql`
    query findContact($phoneNumber: String!, $project: String!) {
      leads(filters: { phoneNumber: { eq: $phoneNumber }, project: { eq: $project } }) {
        data {
          id
        }
      }
    }
  `;

  try {
    const { data } = await client.query({
      query: findContactQuery,
      variables: {
        phoneNumber: formatPhoneNumber2(contactData.phoneNumber),
        project: contactData.project,
      },
      fetchPolicy: 'no-cache',
    });

    const existingContactId = data.leads.data.length > 0 ? data.leads.data[0].id : null;

    // Step 2: Determine mutation type based on existence of contact
    const mutation = existingContactId
      ? gql`
          mutation updateLead($id: ID!, $data: LeadInput!) {
            updateLead(id: $id, data: $data) {
              data {
                id
                attributes {
                  name
                  phoneNumber
                  project
                  sourceDate
                  called
                  interaction
                  status
                  contacted
                  phoneId
                  requestType
                  process
                  stage
                  task
                  delegate
                  address
                  advUrl
                  advUrlDate
                  facebookUrl
                  notionUrl
                }
              }
            }
          }
        `
      : gql`
          mutation createLead($data: LeadInput!) {
            createLead(data: $data) {
              data {
                id
                attributes {
                  name
                  phoneNumber
                  project
                  sourceDate
                  rating
                  called
                  contacted
                  phoneId
                  requestType
                  process
                  stage
                  task
                  delegate
                  address
                  advUrl
                  advUrlDate
                  facebookUrl
                  notionUrl
                }
              }
            }
          }
        `;

    // Step 3: Execute the mutation
    const result = await client.mutate({
      mutation,
      variables: existingContactId ? { id: existingContactId, data: contactData } : { data: contactData },
    });

    return existingContactId ? result.data.updateLead.data : result.data.createLead.data;
  } catch (error) {
    console.error('Error in createOrUpdateContactByKeys:', error);
    throw error;
  }
}
